// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address fuzzedBaseToken, address caller, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {
        vm.assume(fuzzedBaseToken != address(0) || true);
        feeRate = uint16(bound(feeRate, 0, 5000));
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.initialize(fuzzedBaseToken, address(0x1234), vBase, vNft, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.baseToken() == fuzzedBaseToken);
        } else {
            assertTrue(ok);
        }
    }
}
